create function public.a1_skybox_probe_save() returns jsonb language plpgsql security definer set search_path='' as $$ declare actor uuid; sid uuid; result jsonb; errcode text; errcontext text; errmessage text; begin select p.user_id into actor from public.a1_account_profiles p where p.username='jv'; select s.auth_session_id into sid from public.a1_activity_sessions s where s.user_id=actor and ended_at is null order by started_at desc limit 1; if actor is null or sid is null then return jsonb_build_object('code','NO_SESSION'); end if; begin result:=public.a1_skybox_service('configure',jsonb_build_object('actor',actor,'session',sid,'accountId',coalesce((select account_id from a1_skybox_private.connection where id),'123'),'applicationToken','SYNTHETIC-APP','apiToken','SYNTHETIC-API','pageBases','{"customer":1,"vendor":1,"invoice":1,"purchase":1,"inventory":1}'::jsonb)); raise exception using errcode='ZX001',message='rollback successful probe'; exception when sqlstate 'ZX001' then return jsonb_build_object('code','PASS','rolledBack',true); when others then get stacked diagnostics errcode=returned_sqlstate,errcontext=pg_exception_context,errmessage=message_text; return jsonb_build_object('code',errcode,'context',errcontext,'message',errmessage,'rolledBack',true); end; end $$; revoke all on function public.a1_skybox_probe_save() from public,anon,authenticated; grant execute on function public.a1_skybox_probe_save() to service_role;
